import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { SpreadsheetFile, Workbook } from "@oai/artifact-tool";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const DOCS_ROOT = process.env.INSPECTION_DOCS_ROOT?.trim()
  ? path.resolve(process.env.INSPECTION_DOCS_ROOT)
  : path.join(os.homedir(), "Desktop", "Inspection Documentation");
const OUT = path.join(DOCS_ROOT, "05_UI_UX_AND_STORYBOARDS", "outputs", "claude-design-approval-pack");

const refs = [
  ["R01", "MIM MVP1 product contract and 20 implementation storyboards", "Internal authority", "Requirements, journeys, states, handoffs, KSA inspection context, and no-regression constraints.", `${ROOT}/product-contract/00_START_HERE.md`, "Binding authority; not a visual style source."],
  ["R02", "Saqeel DEC-011 and current tokens", "Internal visual authority", "Near-black indigo/violet identity, semantic status colors, EN/AR typography, dark/light themes.", `${ROOT}/product-contract/governance/DECISIONS_ACCEPTED_2026-07-12_SAQEEL.yaml`, "Binding visual language for every screen."],
  ["R03", "SafetyCulture Inspections, Issues, Actions", "Inspection-domain benchmark", "Guided inspection completion, required questions, flagged responses, action assignment, evidence and audit continuity.", "https://help.safetyculture.com/000009", "Borrow inspection interaction principles only; do not copy layout, icons, language, or brand."],
  ["R04", "SafetyCulture inspection management", "Inspection-domain benchmark", "Answer types, corrective actions, instant reports, calculations, drill-down analytics and audit trails.", "https://safetyculture.com/inspections-and-reports", "Use as evidence that inspection-to-action continuity is market-proven."],
  ["R05", "Microsoft Dynamics 365 Field Service mobile", "Field-service benchmark", "Offline-first field work, calendar, directions, camera/video, signatures, forced sync and checklists.", "https://learn.microsoft.com/en-us/dynamics365/field-service/mobile/overview", "Use operational principles; avoid Dynamics chrome and model-driven visual density."],
  ["R06", "Microsoft Dynamics 365 Schedule Board", "Dispatch benchmark", "Resource timelines, map/list synchronization, saved filters, assignment constraints, alerts, legends and contextual details.", "https://learn.microsoft.com/en-us/dynamics365/field-service/work-with-schedule-board", "Use dispatcher mental model; do not reproduce the schedule-board UI."],
  ["R07", "ArcGIS Field Maps", "GIS/field benchmark", "Maps, tasks, smart forms, geofences, location sharing, offline areas and field data collection.", "https://doc.arcgis.com/en/field-maps/get-started/get-started.htm", "Use truthfulness, offline readiness and spatial-context principles; Saqeel remains provider-agnostic."],
  ["R08", "ArcGIS Field Maps offline and attachments", "GIS/evidence benchmark", "Offline basemaps, layer readiness, attachment delivery, EXIF metadata, media constraints and sync preparation.", "https://doc.arcgis.com/en/field-maps/latest/prepare-maps/configure-the-map.htm", "Use for readiness and failure-state anatomy; do not imply ArcGIS is the chosen runtime provider."],
  ["R09", "ArcGIS Dashboards", "Operations benchmark", "Map-driven operational dashboards where selections filter lists/charts and all elements expose the same live context.", "https://doc.arcgis.com/en/dashboards/latest/get-started/create-a-dashboard.htm", "Use coordinated-view behavior; avoid decorative command-center theatrics."],
  ["R10", "Camunda Modeler", "Workflow benchmark", "States, decisions, forms, process tests, stakeholder comments and deployable governed models.", "https://camunda.com/platform/modeler/", "Use model-test-publish clarity; do not copy BPMN-specific branding or controls."],
  ["R11", "SAP Fiori list report and object page", "Enterprise UX benchmark", "Role-oriented overview, searchable/filterable object lists, object pages, wizards and adaptive list-detail layouts.", "https://www.sap.com/design-system/fiori-design-web/v1-145/page-types/floorplans/when-to-use-which-floorplan", "Use predictable enterprise information architecture; Saqeel styling and terminology remain distinct."],
  ["R12", "IBM Carbon data table and tokens", "Enterprise component benchmark", "Accessible dense tables, batch actions, expandable rows, keyboard behavior, semantic tokens and theme consistency.", "https://carbondesignsystem.com/components/data-table/usage/", "Use component behavior and accessibility discipline; do not import Carbon visuals."],
  ["R13", "Apple Human Interface Guidelines — iPad sidebars", "iPad interaction benchmark", "Adaptable sidebar/tab behavior, split views, hiding navigation, succinct hierarchy and large-screen touch use.", "https://developer.apple.com/design/human-interface-guidelines/sidebars", "Use iPad ergonomics without pretending the PWA is a native Apple app."],
  ["R14", "GOV.UK password and validation patterns", "Government-service benchmark", "Show/hide password, neutral authentication errors, clear error summaries, focus management and preserved form input.", "https://design-system.service.gov.uk/components/password-input/", "Use security and accessibility behavior; retain Saqeel visual language."],
  ["R15", "NIST SP 800-63B-4", "Authentication assurance", "Password handling, failed-attempt controls and verifier expectations.", "https://nvlpubs.nist.gov/nistpubs/SpecialPublications/NIST.SP.800-63B-4.pdf", "Security rationale only; does not prescribe the visual design."],
];

const rows = [];
function add(x) {
  rows.push({
    governed: x.governed ?? "Yes",
    requirementScope: x.requirementScope ?? "Filter the 493-row acceptance ledger and 478-row traceability by this screen and journey; preserve every matched row.",
    status: "READY FOR DESIGN TEAM REVIEW",
    rejectionRisk: x.rejectionRisk ?? "Low",
    diffStars: x.diffStars ?? 5,
    readinessGrade: x.readinessGrade ?? 5,
    ...x,
  });
}

// Authentication and access — supplemental design surfaces around the 38 governed screens.
add({seq:1,promptId:"CD-001",governed:"Supplemental",screenId:"AUTH-01",channel:"Authentication",name:"Unified sign-in — the inspection story",route:"/login",persona:"All personas",journey:"Cross-channel entry",engines:"ENG-06, ENG-12",code:"apps/web/src/app/login",job:"Authenticate once and understand, within seconds, what Saqeel governs.",thesis:"A calm credential surface paired with one truthful illustrative KSA inspection journey; identity is resolved after sign-in, never self-declared.",why:"A separate admin/inspector selector is security theatre. One entry point reduces confusion and makes the product story visible without exposing operational data.",differentiator:"The public map is not decoration: it narrates Plan → Inspect → Review → Decide using one sample route and clearly labels itself illustrative.",outlier:"Public surface must feel premium without showing real factories, live positions, risk counts or internal consoles.",references:"R01, R02, R07, R09, R14, R15",influence:"Government-grade credential clarity plus a map-led product narrative grounded in the actual inspection lifecycle.",notCopied:"No ArcGIS dashboard chrome, GOV.UK styling, stock factory hero, or persona tabs.",objects:"Saqeel lockup; email/password; show password; neutral error; reset link; language/theme; illustrative KSA map; four-step inspection strip; demo-only gated helper.",states:"Default; invalid credentials; busy; keyboard focus; light/dark; EN/AR; tile unavailable; offline fallback; demo removed.",blindSpots:"Demo credentials must disappear before release; map tiles may fail; story panel must collapse gracefully on smaller screens; no text over imagery.",designDirection:"Make the credential panel solid and quiet. Make the map panel feel like a curated inspection dossier opening sequence, not a marketing landing page.",repoReads:"LoginClient.tsx; StoryPanel.tsx; login.css; DEC-011; ERR-AUTH-001; login-v4 evidence",batch:"B1 — Access and shell"});
add({seq:2,promptId:"CD-002",governed:"Supplemental",screenId:"AUTH-02",channel:"Authentication",name:"Password recovery and reset",route:"/login (forgot states); /reset",persona:"All personas",journey:"Cross-channel recovery",engines:"ENG-12",code:"apps/web/src/app/login/LoginClient.tsx; apps/web/src/app/reset",job:"Recover access safely without learning whether an account exists or losing confidence.",thesis:"A single focused recovery journey using the same shell, with neutral confirmation and explicit next-step timing.",why:"Recovery is where government services often lose trust. Consistent language, preserved input and visible focus reduce abandonment and information leakage.",differentiator:"Recovery is treated as a traceable trust event, not a generic modal bolted onto login.",outlier:"The confirmation must be useful while remaining account-neutral; expired or reused links need recoverable states.",references:"R02, R14, R15",influence:"GOV.UK error and password patterns combined with Saqeel audit truth.",notCopied:"No generic success confetti, account-existence hint, or separate visual brand.",objects:"Email field; error summary; neutral sent state; new-password fields; strength guidance only if supported; expired-link recovery; return to sign-in.",states:"Invalid email format; transport failure; neutral success; expired link; already-used link; password validation; completed reset.",blindSpots:"Current reset behavior must remain anti-enumeration; email delivery provider status must be truthful; do not invent password rules.",designDirection:"Keep the story map subdued or absent during recovery so the user has one job; preserve the same Saqeel trust footer and typography.",repoReads:"LoginClient.tsx; ResetClient.tsx; audit.ts; ERR-AUTH-001",batch:"B1 — Access and shell"});
add({seq:3,promptId:"CD-003",governed:"Supplemental",screenId:"AUTH-03",channel:"Authentication",name:"Role resolution, unauthorized and no workspace",route:"/launch; protected-route state",persona:"All authenticated personas",journey:"Cross-channel routing",engines:"ENG-12",code:"apps/web/src/app/launch/page.tsx; apps/web/middleware.ts; apps/web/src/components/Shell.tsx",job:"Reach the correct workspace or receive a safe, actionable denial.",thesis:"Role resolution is nearly invisible when successful and unmistakably safe when a role is missing, expired or outside scope.",why:"The present fallback to /admin is an avoidable trust and security smell. Unknown roles need a neutral no-workspace destination.",differentiator:"The denial explains access scope, session identity and support path without exposing other modules.",outlier:"Authenticated-but-unassigned, multi-role, stale-role and wrong-channel states differ from unauthenticated login.",references:"R01, R02, R11, R14",influence:"Enterprise role-based launch behavior with government-service error clarity.",notCopied:"No portal chooser, admin leak, or broad app menu before authorization.",objects:"Resolving indicator; destination label; account identity; no-workspace panel; safe sign-out; request-support path; correlation/audit reference.",states:"Resolving; one role; multiple roles; no role; unauthorized route; expired session; network failure.",blindSpots:"Changing fallback behavior is an implementation/security decision; design must flag it for approval rather than silently change routing.",designDirection:"Use a compact transition state, not a dashboard. The exception screen should feel deliberate and secure, not like a 404.",repoReads:"launch/page.tsx; middleware.ts; rbac_matrix.csv; personas.yaml",batch:"B1 — Access and shell",rejectionRisk:"Medium"});

// Admin control plane.
add({seq:4,promptId:"CD-004",screenId:"SCR-ADM-001",channel:"Admin",name:"Admin control-plane home",route:"/admin",persona:"Compliance, Business and Technical Admin",journey:"P00",engines:"ENG-01..ENG-12",code:"apps/web/src/app/admin/page.tsx",job:"Know what is healthy, what is draft, what is blocked and what needs approval before runtime is affected.",thesis:"A configuration command center organized around governance lifecycle rather than module shortcuts.",why:"Admin engines are control planes. Counts alone cannot reveal dependency risk, unpublished change, approval debt or runtime consumption.",differentiator:"A ‘configuration health spine’ links Draft → Validate → Approve → Publish → Runtime evidence across all engines.",outlier:"One broken or stale engine must be isolated without implying the entire platform is down.",references:"R01, R02, R09, R11, R12",influence:"ArcGIS operational attention hierarchy plus Fiori role overview and Carbon status discipline.",notCopied:"No generic KPI-card dashboard or wall of equal tiles.",objects:"Health summary; pending approvals; publish blockers; runtime version map; dependency warnings; recent audit; engine ownership; direct actions.",states:"Healthy; drafts pending; approval overdue; publish blocked; degraded service; unauthorized; empty new environment.",blindSpots:"Current page shows counts but not approval/dependency health; notification/SLA lacks dedicated route; freshness must be visible.",designDirection:"Make the first screen answer ‘what can harm tomorrow’s inspections?’ in under 30 seconds.",repoReads:"admin/page.tsx; engine_settings; SCR-ADM-001; SB03/SB18",batch:"B2A — Admin governance"});
add({seq:5,promptId:"CD-005",screenId:"SCR-ADM-010",channel:"Admin",name:"Regulation library",route:"/admin/regulations",persona:"Compliance Admin",journey:"P00",engines:"ENG-01, ENG-12",code:"apps/web/src/app/admin/regulations",job:"Find, compare and govern regulations by lifecycle, applicability and effective date.",thesis:"A legal-content library where version status and downstream impact are more prominent than edit controls.",why:"A regulation is not a row; it is the source of clauses, questions, violations and reports.",differentiator:"Each regulation exposes an impact footprint before it is opened: mapped items, packages, active inspections and future effective date.",outlier:"Overlapping effective dates, orphan clauses and superseded versions must be obvious.",references:"R01, R02, R11, R12",influence:"Fiori list-report clarity and Carbon dense-table accessibility, adapted to regulatory provenance.",notCopied:"No spreadsheet-like CRUD grid or unexplained legal badges.",objects:"Search/filter; lifecycle tabs; owner; effective dates; source provenance; impact count; version; create draft; validation markers.",states:"No records; loading; filtered empty; invalid dates; publish blocked; published locked; unauthorized.",blindSpots:"Legal text may be long and bilingual; list must not imply editing a published record; impact counts need source timestamps.",designDirection:"Prioritize lifecycle and impact. Use dense rows with expandable provenance, not oversized cards.",repoReads:"admin/regulations/page.tsx; actions.ts; SCR-ADM-010; field_dictionary.csv",batch:"B2A — Admin governance"});
add({seq:6,promptId:"CD-006",screenId:"SCR-ADM-011",channel:"Admin",name:"Regulation detail and version",route:"/admin/regulations (detail mode)",persona:"Compliance Admin; Approver",journey:"P00",engines:"ENG-01, ENG-12",code:"apps/web/src/app/admin/regulations",job:"Edit a draft, understand dependencies, compare versions and publish safely.",thesis:"A document dossier with a persistent lifecycle rail and an immutable published-version boundary.",why:"The highest-risk action is not editing text; it is changing the meaning consumed by future inspections.",differentiator:"Clause-to-runtime trace: regulation clause → inspection item → package → evidence/violation/report.",outlier:"A published version is locked while a successor draft may coexist; reviewers need side-by-side meaning changes.",references:"R01, R02, R10, R11",influence:"Fiori object page plus Camunda-like governed publish confidence.",notCopied:"No word-processor clone or hidden dependency drawer.",objects:"Metadata header; clause navigator; applicability; legal reference; version compare; dependency map; audit timeline; validate/submit/approve/publish.",states:"Draft; validation errors; submitted; approved; published locked; superseded; dependency conflict.",blindSpots:"Bilingual clause display and long legal text; maker-checker role; unresolved mappings must block publish.",designDirection:"Keep the legal document readable while making lifecycle and downstream impact impossible to miss.",repoReads:"regulations page/actions; state_transitions.csv; rbac_matrix.csv",batch:"B2A — Admin governance"});
add({seq:7,promptId:"CD-007",screenId:"SCR-ADM-020",channel:"Admin",name:"Inspection item catalogue",route:"/admin/items",persona:"Compliance Admin; Form Admin",journey:"P00",engines:"ENG-01, ENG-02, ENG-07",code:"apps/web/src/app/admin/items",job:"Define reusable inspection questions with unambiguous runtime meaning.",thesis:"A semantic component catalogue: response type, requirement rule, evidence, scoring and clause linkage are visible together.",why:"Questions that look similar can behave differently in the field; the catalogue must prevent semantic ambiguity.",differentiator:"A compact ‘runtime preview strip’ shows how the item behaves on iPad and what finding/evidence it can trigger.",outlier:"Conditional items, duplicate codes and response meanings that change across versions.",references:"R01, R02, R03, R07, R11, R12",influence:"SafetyCulture form semantics, Field Maps form configuration and enterprise catalogue patterns.",notCopied:"No generic survey builder or template marketplace look.",objects:"Item code/title; clause; response model; required/conditional rule; evidence; scoring; guidance; usage count; runtime preview.",states:"Empty; duplicate; invalid mapping; conditional rule error; deactivated; published-use warning.",blindSpots:"Changing a reused item can affect multiple packages; Arabic guidance length; evidence policy must come from configuration.",designDirection:"Make meaning and reuse risk the visual center, not the create-item form.",repoReads:"admin/items/page.tsx; actions.ts; package components; SCR-ADM-020",batch:"B2A — Admin governance"});
add({seq:8,promptId:"CD-008",screenId:"SCR-ADM-030",channel:"Admin",name:"Package library",route:"/admin/packages",persona:"Form Admin; Compliance Admin",journey:"P00",engines:"ENG-02, ENG-12",code:"apps/web/src/app/admin/packages",job:"Find the right package version and know whether it is safe for use.",thesis:"A versioned product library where coverage, dependencies and effective scope lead the hierarchy.",why:"Planners and inspectors depend on the published package version; a package name alone is insufficient.",differentiator:"Coverage fingerprint summarizes sections, items, evidence rules, activities and unresolved dependencies.",outlier:"Old inspections must remain pinned to old package versions while new visits use the new version.",references:"R01, R02, R11, R12",influence:"Fiori list/object pairing and Carbon expandable data rows.",notCopied:"No card marketplace or static template gallery.",objects:"Package/version; scope; status; effective date; dependency health; usage count; coverage fingerprint; clone/preview/validate/publish.",states:"No package; draft; submitted; published; superseded; unresolved item; active dependency.",blindSpots:"Version immutability and effective-date overlap; preview must match field runtime; package size/offline footprint.",designDirection:"Treat each package as a deployable governed artifact with visible consumers.",repoReads:"admin/packages/page.tsx; package_versions; SCR-ADM-030",batch:"B2B — Admin studios"});
add({seq:9,promptId:"CD-009",screenId:"SCR-ADM-031",channel:"Admin",name:"Package and form designer",route:"/admin/packages (designer mode)",persona:"Form Admin",journey:"P00",engines:"ENG-01, ENG-02, ENG-07, ENG-08",code:"apps/web/src/app/admin/packages",job:"Compose sections, rules, evidence and actions, then prove the package behaves correctly.",thesis:"A three-pane studio—structure, field canvas, rule inspector—with an always-visible validation and runtime preview contract.",why:"A constrained builder must expose logic and downstream consequences without becoming an ungoverned no-code platform.",differentiator:"‘Inspection consequence preview’ shows not only the question but the evidence, violation, action and review outcome it can produce.",outlier:"Circular conditions, hidden mandatory items, inaccessible field layouts and rules that work online but not offline.",references:"R01, R02, R03, R07, R10, R11",influence:"SafetyCulture inspection authoring, Field Maps form configuration and Camunda test-before-deploy discipline.",notCopied:"No drag-anything canvas, BPMN palette, or consumer-form aesthetic.",objects:"Section tree; item canvas; inspector; condition builder; evidence rule; action trigger; bilingual preview; simulation; validation; impact; publish controls.",states:"Clean draft; unsaved; validation errors; circular logic; preview; test pass/fail; submitted; published locked.",blindSpots:"Keyboard reordering; RTL preview; offline behavior; dependency impact; one screen can become too dense without focus mode.",designDirection:"This is a flagship differentiator. Make complex configuration feel controlled, explainable and testable.",repoReads:"PackageEditor.tsx; PackagePreview.tsx; DraftEditor/ImpactPanel/PublishControls; SCR-ADM-031",batch:"B2B — Admin studios"});
add({seq:10,promptId:"CD-010",screenId:"SCR-ADM-040",channel:"Admin",name:"Violation catalogue",route:"/admin/violations",persona:"Compliance Admin",journey:"P00",engines:"ENG-08, ENG-12",code:"apps/web/src/app/admin/violations",job:"Govern violation codes, legal anchors, severity and applicability.",thesis:"A legal taxonomy view where orphaned or overlapping violations surface before operational use.",why:"Violations are generated outcomes, not inspector free text; legal basis and version are essential.",differentiator:"Each violation displays a trace ribbon from triggering response to legal clause and corrective-action consequence.",outlier:"Orphan mappings, duplicate codes, deactivation while historical records remain valid.",references:"R01, R02, R04, R11, R12",influence:"Inspection issue/action continuity with enterprise catalogue discipline.",notCopied:"No simple severity-colored table that hides legal meaning.",objects:"Code/title; level; category; legal basis; applicability; active dates; trigger mapping; usage count; lifecycle actions.",states:"Empty; duplicate; orphan; active; future; deactivated; locked by use.",blindSpots:"Severity cannot be communicated by color only; legal basis may be missing; historical references must persist.",designDirection:"Use compact, auditable rows with a strong trace drill-in.",repoReads:"admin/violations/page.tsx; actions.ts; SCR-ADM-040",batch:"B2A — Admin governance"});
add({seq:11,promptId:"CD-011",screenId:"SCR-ADM-041",channel:"Admin",name:"Penalty mapping",route:"/admin/violations (penalty mode)",persona:"Compliance Admin; Approver",journey:"P00",engines:"ENG-08, ENG-12",code:"apps/web/src/app/admin/violations",job:"Map violations to approved penalty records and detect conflicts before publish.",thesis:"A relationship workspace, not a second catalogue: violation on one side, penalty rule on the other, validation in the middle.",why:"Cardinality, ranges, repeat rules and legal anchors create risks invisible in a flat form.",differentiator:"Conflict lens highlights overlaps, gaps and repeated-offence escalations with example outcomes.",outlier:"One-to-one constraints, overlapping effective periods and penalty context that inspectors may view but cannot edit.",references:"R01, R02, R10, R11, R12",influence:"Decision-model transparency and enterprise relationship management.",notCopied:"No spreadsheet matrix with unexplained colored cells.",objects:"Violation selector; penalty record; range; repeat rule; cardinality; legal basis; version; examples; validate/publish.",states:"Unmapped; valid; overlap; missing legal basis; submitted; approved; published locked.",blindSpots:"Do not invent monetary values or legal rules; examples must be configuration-derived; maker-checker.",designDirection:"Make conflicts and legal provenance more visible than the mapping controls.",repoReads:"violations page/actions; penalty_mappings; SCR-ADM-041",batch:"B2A — Admin governance",rejectionRisk:"Medium"});
add({seq:12,promptId:"CD-012",screenId:"SCR-ADM-050",channel:"Admin",name:"Workflow library",route:"/admin/workflows",persona:"Workflow Admin",journey:"P00",engines:"ENG-03, ENG-11, ENG-12",code:"apps/web/src/app/admin/workflows",job:"Find workflow definitions and understand version, coverage and validation health.",thesis:"A deployable-process library showing object, active version, effective date and failed tests.",why:"Workflow cannot be reduced to status labels; users need confidence that guards and side effects are valid.",differentiator:"Each workflow has a miniature lifecycle signature showing states, terminals, SLA and unresolved paths.",outlier:"Unreachable states, circular terminal paths and active versions used by in-flight cases.",references:"R01, R02, R10, R11, R12",influence:"Camunda model governance plus Fiori deployable-object library.",notCopied:"No BPMN diagram thumbnails as the only summary.",objects:"Workflow/object; version; lifecycle signature; status; effective date; tests; runtime cases; clone/open/publish.",states:"Empty; draft; test failures; submitted; published; superseded; in-use warning.",blindSpots:"Current route consolidates list and designer; preserve clear mode separation; no direct runtime state mutation.",designDirection:"Make workflow health legible before opening the designer.",repoReads:"admin/workflows/page.tsx; actions.ts; SCR-ADM-050",batch:"B2B — Admin studios"});
add({seq:13,promptId:"CD-013",screenId:"SCR-ADM-051",channel:"Admin",name:"Workflow designer",route:"/admin/workflows (designer mode)",persona:"Workflow Admin; Approver",journey:"P00",engines:"ENG-03, ENG-11, ENG-12",code:"apps/web/src/app/admin/workflows",job:"Configure and test states, transitions, actors, guards, SLA and side effects.",thesis:"A state-machine studio with model canvas, transition inspector and scenario simulator sharing one truth.",why:"Visual elegance is dangerous if guards, actors and side effects are hidden. The model must be explainable and testable.",differentiator:"Scenario replay animates a real inspection case through guards, notifications and audit events before publish.",outlier:"Unauthorized transitions, returned-scope loops, unreachable states and circular terminal logic.",references:"R01, R02, R10, R11",influence:"Camunda’s model/test/deploy concept adapted to the accepted Saqeel state machine.",notCopied:"No generic BPMN editor, free-form diagramming, or direct status-edit tool.",objects:"State canvas; transition panel; actor/guard builder; required fields; side effects; SLA/notification; scenario inputs; test results; impact; publish.",states:"Draft; invalid edge; unreachable state; failing simulation; passed; submitted; approved; published locked.",blindSpots:"Canvas accessibility; RTL; model versioning; test data; visual graph must not imply unimplemented transition types.",designDirection:"Another flagship. Optimize for regulatory confidence, not diagram novelty.",repoReads:"workflows page/actions; state_transitions.csv; SCR-ADM-051",batch:"B2B — Admin studios"});
add({seq:14,promptId:"CD-014",screenId:"SCR-ADM-060",channel:"Admin",name:"Risk configuration",route:"/admin/risk",persona:"Risk Owner; Compliance Admin",journey:"P00",engines:"ENG-04, ENG-12",code:"apps/web/src/app/admin/risk",job:"Understand and govern the approved risk model and test its output on representative factories.",thesis:"A reproducibility workspace: model version, drivers, weights, thresholds, sources and sample calculation on one screen.",why:"A decorative risk gauge cannot support targeting or audit. Users must see why a score exists.",differentiator:"‘Why this factory?’ simulation connects input provenance to score, band and planning consequence.",outlier:"Missing source data, stale inputs, model version changes and threshold-edge factories.",references:"R01, R02, R11, R12",influence:"Enterprise analytical object-page patterns; internal accepted risk model is the only source of values.",notCopied:"No black-box AI score, radar chart theatre or invented advanced Risk Studio.",objects:"Version; drivers; weights; thresholds; source freshness; formula reference; sample factory; calculation trace; compare versions; validate/publish.",states:"Complete; missing source; stale; threshold edge; test pass/fail; draft; published.",blindSpots:"DEC-001 values are interim owner-revisable; avoid implying causal certainty; explain denominator and version.",designDirection:"Make risk explainability concrete and calm, with numbers traceable line by line.",repoReads:"admin/risk/page.tsx; DEC-001; factories risk fields; SCR-ADM-060",batch:"B2B — Admin studios"});
add({seq:15,promptId:"CD-015",screenId:"SCR-ADM-070",channel:"Admin",name:"GIS and geofence studio",route:"/admin/gis",persona:"GIS Admin; Technical Admin",journey:"P00",engines:"ENG-06, ENG-12",code:"apps/web/src/app/admin/gis",job:"Validate factory locations, geofences and exception policy before field use.",thesis:"A map-led governed geometry workspace comparing official, geocoded and field-verified truth.",why:"A map alone creates false confidence. Source, accuracy, geometry validity and approval status must travel with every location.",differentiator:"Location confidence stack shows official point, verified point, boundary, geofence and last field evidence without overwriting provenance.",outlier:"Invalid polygons, wrong official coordinates, external tiles unavailable and centroid approximations.",references:"R01, R02, R07, R08, R09",influence:"Field Maps preparation/offline diagnostics and map-linked operational controls.",notCopied:"No ArcGIS desktop clone or unlabeled choropleth.",objects:"Layer controls; factory search; source points; polygon/radius; accuracy/arrival thresholds; override roles; validation; preview; impact; publish.",states:"Valid; invalid geometry; missing coordinate; source mismatch; tile unavailable; stale; draft; published.",blindSpots:"Provider abstraction; privacy; attribution; thresholds must come from DEC-002; KSA boundaries need authoritative source.",designDirection:"Make uncertainty visible. The premium quality comes from provenance and confidence, not map decoration.",repoReads:"admin/gis/page.tsx; GeoMap.tsx; DEC-002/008; SCR-ADM-070",batch:"B2B — Admin studios"});
add({seq:16,promptId:"CD-016",screenId:"SCR-ADM-080",channel:"Admin",name:"Notification and SLA rules",route:"/admin (current consolidated surface)",persona:"Business Admin; Technical Admin",journey:"P00",engines:"ENG-11, ENG-12",code:"apps/web/src/app/admin/page.tsx; apps/web/src/components/NotificationBell.tsx",job:"Configure event, recipient, template, timer and escalation rules and know delivery-provider truth.",thesis:"An event-to-outcome rule studio where timing, recipients and delivery state are tested before activation.",why:"Notifications are operational controls, not message templates. Wrong recipients or silent provider failure can break SLA.",differentiator:"A timeline simulator previews reminder, breach and escalation against the accepted work calendar.",outlier:"Provider unavailable, partial-channel delivery, duplicate notification and paused SLA during correction.",references:"R01, R02, R10, R11, R12",influence:"Workflow test discipline plus enterprise rule and status patterns.",notCopied:"No marketing-automation campaign builder.",objects:"Event catalogue; recipient rules; channels; template; work calendar; reminders; escalation; provider status; test; delivery audit; activate.",states:"Draft; invalid recipient; provider pending; test sent/failed; active; paused; breached; deactivated.",blindSpots:"No dedicated route currently; provider adapters remain open; do not imply outbound delivery works when only outbox is present.",designDirection:"Keep provider truth and SLA timeline visible at all times.",repoReads:"admin/page.tsx; NotificationBell.tsx; DEC-003/007; SCR-ADM-080",batch:"B2B — Admin studios",rejectionRisk:"Medium"});
