add({seq:35,promptId:"CD-035",screenId:"SCR-IPAD-620",channel:"iPad",name:"Journey and geofence check-in",route:"/field/:visitId (journey mode)",persona:"Inspector",journey:"P06A",engines:"ENG-03, ENG-06, ENG-10, ENG-11, ENG-12",code:"apps/web/src/app/field/[visitId]/Startup.tsx",job:"Travel, understand route/ETA, prove arrival and check in or request a governed exception.",thesis:"A map-led journey screen with one dominant next action and a geofence confidence card.",why:"Field users cannot interpret raw GPS accuracy, distance and boundary data while moving.",differentiator:"Check-in proof combines boundary, distance, GPS accuracy, timestamp, device and exception path in one audit-ready card.",outlier:"No GPS, weak accuracy, outside geofence, route deviation, offline maps and wrong official location.",references:"R01, R02, R05, R07, R08, R13",influence:"ArcGIS geofence/offline patterns and field-service travel status, grounded in DEC-002.",notCopied:"No ride-hailing map clone or automatic check-in without proof.",objects:"Route map; ETA/distance; privacy/freshness; GPS accuracy; start journey; arrival; geofence ring; check-in proof; retry; override request; offline indicator.",states:"Not started; on journey; arrived; inside; outside; weak GPS; offline; deviation; override pending/approved/denied.",blindSpots:"Provider abstraction; battery/privacy; thresholds from config; no false live navigation claim; indoor GPS exception.",designDirection:"Flagship spatial interaction. Make complex location confidence understandable at a glance.",repoReads:"Startup.tsx; GeoMap.tsx; DEC-002/008; ERR-GEO-001/002",batch:"B5 — iPad field"});
