add({seq:38,promptId:"CD-038",screenId:"SCR-IPAD-650",channel:"iPad",name:"Findings, violations and actions",route:"/field/inspection/:id (findings mode)",persona:"Inspector",journey:"P08",engines:"ENG-01, ENG-02, ENG-07, ENG-08, ENG-12",code:"apps/web/src/app/field/inspection/[id]/Workspace.tsx",job:"Record an observation and understand the configured violation, penalty context and corrective action it produces.",thesis:"A cause-to-consequence workspace anchored in the finding, with system-generated legal outcomes clearly distinguished from inspector input.",why:"Inspectors must not manually invent violations or penalties, yet they need context to capture sufficient evidence.",differentiator:"Trace ribbon links observation → clause → evidence → configured violation → penalty context → action form.",outlier:"Rule unavailable, missing evidence, multiple violations, incomplete action form and no applicable penalty.",references:"R01, R02, R03, R04, R11",influence:"SafetyCulture issue-to-action flow combined with Saqeel’s regulation/violation traceability.",notCopied:"No free-form incident report or editable penalty selector.",objects:"Finding form; severity; clause; linked response/evidence; generated violation; penalty context read-only; action owner/due/correction; completion validation.",states:"Draft; missing evidence; rule unavailable; generated; action incomplete; completed; submitted locked.",blindSpots:"Inspector authority boundaries; cardinality; legal basis; offline rule availability; no AI final decision.",designDirection:"Make the distinction between observed fact and configured legal consequence unmistakable.",repoReads:"Workspace.tsx; violation mappings; action_forms; SCR-IPAD-650",batch:"B5 — iPad field"});
add({seq:39,promptId:"CD-039",screenId:"SCR-IPAD-660",channel:"iPad",name:"Pre-submit validation and immutable submission",route:"/field/inspection/:id (submit mode)",persona:"Inspector",journey:"P09",engines:"ENG-03, ENG-07, ENG-09, ENG-10, ENG-11, ENG-12",code:"apps/web/src/app/field/inspection/[id]/Workspace.tsx",job:"Resolve every blocker, understand what will lock and submit exactly once.",thesis:"A submission pre-flight converts hundreds of responses into a concise proof of completeness and immutability.",why:"A final button without a manifest encourages accidental incomplete or duplicate submissions.",differentiator:"Immutable receipt previews version, package, evidence manifest, signatures, queued operations and downstream reviewer handoff.",outlier:"Mandatory blocker, offline submit queue, timeout retry, duplicate request and unresolved conflict.",references:"R01, R02, R03, R14",influence:"Inspection completion review and government-service validation summaries, backed by idempotent submission.",notCopied:"No generic checkout summary or celebratory success screen.",objects:"Completion summary; grouped blockers with deep links; evidence manifest; action/signature status; sync truth; immutable warning; submit; receipt; reviewer handoff.",states:"Blocked; ready; offline queued; submitting; timeout; retry existing result; success locked; partial failure prevented.",blindSpots:"Idempotency; queued is not submitted; signatures; PDF generation failure; atomic rollback; exact locked scope.",designDirection:"Flagship trust moment. Make the inspector confident that nothing is missing and nothing will be silently duplicated.",repoReads:"Workspace.tsx; offline.ts; ERR-SUB-001/002; STM-INS-002",batch:"B5 — iPad field"});
add({seq:40,promptId:"CD-040",screenId:"SCR-IPAD-670",channel:"iPad",name:"Returned correction and resubmission",route:"/field/inspection/:id (returned mode)",persona:"Inspector",journey:"P11",engines:"ENG-03, ENG-07, ENG-09, ENG-10, ENG-12",code:"apps/web/src/app/field/inspection/[id]/Workspace.tsx",job:"Understand the reviewer’s exact request, edit only unlocked sections and create version N+1.",thesis:"A correction workspace that makes editable scope, immutable prior content and reviewer reasoning visually explicit.",why:"A generic reopened form risks unauthorized changes and hides the relationship between versions.",differentiator:"Return-contract header shows reviewer comment, due context, unlocked sections and a live change ledger against the prior version.",outlier:"Attempted locked edit, evidence replacement, overdue correction and offline conflict.",references:"R01, R02, R03, R11, R12",influence:"Inspection correction workflows plus semantic version comparison.",notCopied:"No full-form edit mode or ambiguous ‘reopen’ badge.",objects:"Return summary; immutable comment; version lineage; unlocked section nav; locked cues; change ledger; evidence add; blockers; resubmit.",states:"Returned; correction in progress; locked attempt; offline; conflict; ready; resubmitting; version N+1 submitted.",blindSpots:"Selective unlock enforcement; due policy; conflict resolution; prior evidence immutability; reviewer comment cannot be edited.",designDirection:"Make the correction task narrow and reassuring: change only what was asked, prove what changed.",repoReads:"Workspace.tsx; reviews; submission_versions; STM-COR-001/002",batch:"B5 — iPad field"});

