add({seq:42,promptId:"CD-042",screenId:"SCR-VIR-710",channel:"Virtual",name:"Identity and OTP verification",route:"/virtual/:id (verification mode)",persona:"Factory Representative; Inspector; System",journey:"P06B",engines:"ENG-03, ENG-11, ENG-12",code:"apps/web/src/app/virtual/[id]/Room.tsx",job:"Verify participant identity or follow a governed failure/escalation path.",thesis:"A progressive verification panel that communicates state, remaining attempts, cooldown and audit consequence without anxiety.",why:"OTP is a security gate; bypasses or vague failures undermine the entire remote inspection.",differentiator:"Verification receipt connects participant, channel, attempt state, appointment and audit outcome while protecting sensitive data.",outlier:"Identity mismatch, wrong code, cooldown, exhausted attempts and provider unavailable.",references:"R01, R02, R14, R15",influence:"Government authentication clarity and NIST assurance, using accepted OTP configuration.",notCopied:"No banking-app theatrics, fake success, or hidden lockout.",objects:"Masked identity; role; OTP input; resend timer; attempts; channel; verify; mismatch; escalation/reschedule; audit receipt.",states:"Sent; entering; invalid; cooldown; resent; verified; exhausted; provider unavailable; escalated.",blindSpots:"Provider availability; SMS/email fallback; manual exception must be supervisor-approved and audited; Arabic numerals/input.",designDirection:"Make every next step explicit while revealing no unnecessary personal data.",repoReads:"Room.tsx/actions.ts; DEC-007; ERR-VIR-001; SCR-VIR-710",batch:"B6 — Virtual"});
add({seq:43,promptId:"CD-043",screenId:"SCR-VIR-720",channel:"Virtual",name:"Virtual inspection session",route:"/virtual/:id (session mode)",persona:"Inspector; Factory Representative",journey:"P06B/P07/P08",engines:"ENG-01, ENG-02, ENG-03, ENG-07, ENG-11, ENG-12",code:"apps/web/src/app/virtual/[id]/Room.tsx",job:"Conduct a remote inspection, request views/evidence, complete the checklist and close or fall back safely.",thesis:"A governed inspection workspace with the video stage treated as one evidence source beside agenda, checklist and capture—not the whole product.",why:"Video-call clones lose inspection structure; a regulatory session needs identity, evidence requests, notes, progress and fallback.",differentiator:"Evidence request rail timestamps what the inspector asked to see, what was shown, what was captured and whether it was sufficient.",outlier:"Video provider pending, weak connection, participant drop, insufficient evidence and fallback to physical inspection.",references:"R01, R02, R03, R04, R11, R12",influence:"Inspection evidence/action flow and enterprise split-workspace behavior; no video-product imitation.",notCopied:"No Teams/Zoom interface, fake call controls or claimed recording integration.",objects:"Provider-status stage; participants; identity badges; connection quality; agenda/checklist; evidence request rail; notes; capture; session status; fallback/close.",states:"Provider pending; connecting; waiting; active future; degraded; participant dropped; insufficient evidence; fallback physical; closed.",blindSpots:"No integrated video provider; recording consent/retention; bandwidth; external participant accessibility; closure must create review-ready handoff.",designDirection:"Flagship virtual screen. The inspection protocol must remain usable even when video is degraded or unavailable.",repoReads:"Room.tsx/actions.ts; SCR-VIR-720; UX-BS-004; DEC-006/007",batch:"B6 — Virtual",rejectionRisk:"Medium"});

if (rows.length !== 43) throw new Error(`Expected 43 screens, found ${rows.length}`);

// Only materially distinctive, signature interactions receive 5/5.
// Supporting screens target premium 4/5 differentiation through cohesion.
const signatureScreens = new Set([1,4,6,9,13,15,17,21,24,26,27,29,30,31,32,33,34,35,36,37,39,40,43]);
for (const r of rows) {
  r.diffStars = signatureScreens.has(r.seq) ? 5 : 4;
  r.readinessGrade = r.rejectionRisk === "Medium" ? 4 : 5;
}

async function relevantFiles(path) {
  const out = [];
  async function walk(abs) {
    const stat = await fs.stat(abs);
    if (stat.isFile()) {
      if (/\.(tsx|ts|css|scss|json|svg|png|jpe?g|webp)$/i.test(abs)) out.push(abs.slice(ROOT.length + 1));
      return;
    }
    for (const entry of await fs.readdir(abs,{withFileTypes:true})) {
      if (["node_modules",".next","dist","coverage"].includes(entry.name)) continue;
      await walk(`${abs}/${entry.name}`);
    }
  }
  try { await walk(`${ROOT}/${path}`); } catch { out.push(`VERIFY_PATH:${path}`); }
  return out;
}

for (const r of rows) {
  const candidates = [];
  for (const path of r.code.split(";").map(v=>v.trim()).filter(Boolean)) candidates.push(...await relevantFiles(path));
  r.exactFiles = [...new Set(candidates)].join("; ");
}

function promptFor(r) {
  return `CLAUDE DESIGN SCREEN PROMPT — ${r.promptId} / ${r.screenId}\n\n` +
`You are designing ${r.name} for Saqeel MVP1. This is a controlled high-fidelity redesign of an already implemented product, not a greenfield concept.\n\n`+
`MANDATORY REPOSITORY DISCOVERY\nRead AGENTS.md; product-contract/00_START_HERE.md; CURRENT_STATE.md; GATE_STATUS.md; DECISIONS_ACCEPTED_2026-07-12_SAQEEL.yaml; design/claude-design-mvp1/00_START_HERE.md; CURRENT_UI_BASELINE.md; authority/CODE_ROUTE_RECONCILIATION.csv; product-contract/screens/screen_route_catalogue.csv; FABLE_UNDERSTANDING_TRACEABILITY.csv; FABLE_ACCEPTANCE_UNDERSTANDING.csv; and these screen-specific sources: ${r.repoReads}. Inspect the existing implementation at ${r.code}. Record branch, commit and dirty-worktree state. Do not design from screenshots alone.\n\n`+
`CONTRACT\nScreen: ${r.screenId}. Route/mode: ${r.route}. Persona: ${r.persona}. Journey: ${r.journey}. Engines: ${r.engines}. User job: ${r.job} Requirements: ${r.requirementScope}\n\n`+
`DESIGN THESIS\n${r.thesis}\nWhy this way: ${r.why}\nSignature differentiator: ${r.differentiator}\nOutlier/hard case: ${r.outlier}\n\n`+
`INFLUENCE AND ORIGINALITY\nStudy references ${r.references} in the pack’s Reference Library. Adopt this principle: ${r.influence} Explicitly reject: ${r.notCopied} Saqeel’s DEC-011 tokens, typography, dark/light themes, EN/AR behavior and component grammar remain the visual authority.\n\n`+
`MANDATORY OBJECTS\n${r.objects}\nMandatory states: ${r.states}\nBlind spots to resolve visibly: ${r.blindSpots}\nArt direction: ${r.designDirection}\n\n`+
`DELIVERABLE\nProduce code-ready high-fidelity design, not a wireframe. Fit the existing route, React components, server actions, Supabase contracts, RBAC/RLS, state transitions, audit, offline outbox, version immutability and provider truth. Provide: (1) primary populated design; (2) the critical outlier/failure state; (3) applicable dark/light and EN/AR/RTL evidence; (4) desktop or 1024×1366 iPad portrait/landscape as appropriate; (5) component disposition—PRESERVE/UPDATE/CREATE/REMOVE, where REMOVE requires explicit human approval; (6) interaction, state, audit and data annotations; (7) PNG names ${r.promptId}_${r.screenId}_primary.png and ${r.promptId}_${r.screenId}_outlier.png.\n\n`+
`DETERMINISTIC DESIGN-TO-CODE REPLACEMENT CONTRACT\nThe repository-derived candidate file inventory is: ${r.exactFiles}. Verify this inventory against imports and runtime composition before designing; add transitive files only with evidence. For every affected .tsx, .ts, .css, localization or asset file, provide its exact repository-relative path, current responsibility BEFORE this redesign, disposition (PRESERVE/UPDATE/CREATE/REMOVE), responsibility AFTER this redesign, exact component/export/selector/token/design-node affected, and why the change is required. A directory, route or guessed filename is not sufficient. Preserve handlers, server actions, Supabase calls, schemas, RLS/RBAC, audit events, state transitions, localization keys, offline/conflict logic, test selectors and accessibility behavior unless an approved requirement explicitly changes them. Never overwrite the repository during the design phase.\n\n`+
`Return these handoff files with the design: (A) IMPLEMENTATION_MANIFEST_${r.promptId}.yaml containing prompt_id, screen_id, route, source_branch, source_commit, dirty_worktree, design_frame_ids, PNGs, and one file_changes entry per exact path with before_responsibility, disposition, after_responsibility, design_node, code_target, protected_behavior, dependencies, RTL/theme impact, tests and rollback; (B) COMPONENT_MAP_${r.promptId}.csv mapping each design component/state to the existing or proposed code component and CSS selector/token; (C) CLAUDE_CODE_HANDOFF_${r.promptId}.md with the controlled application order: semantic tokens → approved assets → shared components → route composition → localization → tests/evidence; and (D) ACCEPTANCE_CHECKLIST_${r.promptId}.md tracing requirements, states, responsive modes, accessibility and visual evidence. If an exact file or behavior cannot be verified, use HANDOFF_BLOCKED with the missing evidence—never guess. Claude Code may apply only a human-approved manifest on a controlled branch/worktree and must report the resulting diff path by path.\n\n`+
`SELF-CRITICISM LOOP — COMPLETE BEFORE RETURNING\nPass 1: contract coverage—no mapped requirement, state, role, error or negative path missing. Pass 2: inspection-domain plausibility—an inspector/admin/planner/reviewer can explain every object. Pass 3: differentiation—remove generic SaaS/dashboard/form-builder patterns and any copied product styling. Pass 4: cohesion—use the shared Saqeel shell, tokens and components; this screen must look native to all other screens. Pass 5: implementation fit—verify existing files, routes, data, responsiveness, 48px field targets, 16px inputs, WCAG AA, keyboard, focus, reduced motion and RTL. Revise internally until all five passes score 5/5. Return READY_FOR_DESIGN_REVIEW, never self-approve.`;
}

for (const r of rows) r.fullPrompt = promptFor(r);

